def count_substrings(s):
    ans=0
    prefix=[0]*10
    cnt=[ [0]*d for d in range(10) ]  # index 0 unused
    for d in range(1,10):
        cnt[d][0]=1
    for ch in s:
        num=int(ch)
        for d in range(1,10):
            prefix[d]=(prefix[d]*10+num)%d
        if num!=0:
            d=num
            ans+=cnt[d][prefix[d]]
        for d in range(1,10):
            cnt[d][prefix[d]]+=1
    return ans

