#!/usr/bin/env python3
import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N)]
    B = [int(next(it)) for _ in range(N)]
    knownA = []
    knownB = []
    uA = uB = 0
    both_known_sums = set()
    for a,b in zip(A,B):
        if a != -1 and b != -1:
            both_known_sums.add(a+b)
        elif a == -1 and b == -1:
            # both unknown
            uA += 1
            uB += 1
        elif a == -1:
            uA += 1
        elif b == -1:
            uB += 1
    # Collect known values
    for a in A:
        if a != -1:
            knownA.append(a)
    for b in B:
        if b != -1:
            knownB.append(b)
    # If there are both-known pairs
    if both_known_sums:
        if len(both_known_sums) > 1:
            print("No")
            return
        S = next(iter(both_known_sums))
        # Check that S >= all known values
        if S < 0:
            print("No")
            return
        for a in knownA:
            if S - a < 0:
                print("No")
                return
        for b in knownB:
            if S - b < 0:
                print("No")
                return
        # Matching between knownA and knownB
        from collections import Counter
        cntB = Counter(knownB)
        matched = 0
        for a in knownA:
            need = S - a
            if cntB.get(need,0) > 0:
                matched += 1
                cntB[need] -= 1
        unmatchedA = len(knownA) - matched
        unmatchedB = len(knownB) - matched
        if unmatchedA <= uB and unmatchedB <= uA:
            print("Yes")
        else:
            print("No")
        return
    # No both-known pair
    max_known = 0
    for v in knownA + knownB:
        if v > max_known:
            max_known = v
    # Choose S = max_known
    S = max_known
    # Ensure S >= all known values
    # It's automatically true
    # Matching between knownA and knownB for this S
    from collections import Counter
    cntB = Counter(knownB)
    matched = 0
    for a in knownA:
        need = S - a
        if cntB.get(need,0) > 0:
            matched += 1
            cntB[need] -= 1
    unmatchedA = len(knownA) - matched
    unmatchedB = len(knownB) - matched
    if unmatchedA <= uB and unmatchedB <= uA:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()

