"""
Solution for: count-connected-components-in-lcm-graph
Problem ID: lcb_3680

Implement the function below.
"""

from typing import List

class DSU:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x: int) -> int:
        # Path compression
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x: int, y: int) -> None:
        xr = self.find(x)
        yr = self.find(y)
        if xr == yr:
            return
        # Union by rank
        if self.rank[xr] < self.rank[yr]:
            self.parent[xr] = yr
        elif self.rank[xr] > self.rank[yr]:
            self.parent[yr] = xr
        else:
            self.parent[yr] = xr
            self.rank[xr] += 1


class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # Separate numbers into those <= threshold (potential edges) and > threshold (isolated)
        small_values = []
        large_count = 0
        for v in nums:
            if v <= threshold:
                small_values.append(v)
            else:
                large_count += 1

        # Map value to a compact index for DSU
        val_to_idx = {v: i for i, v in enumerate(small_values)}
        m = len(small_values)

        # Edge case: no small numbers
        if m == 0:
            return large_count

        # Prepare buckets for each potential lcm value up to threshold
        buckets = [[] for _ in range(threshold + 1)]

        # For each small number, iterate multiples up to threshold and add to corresponding bucket
        for v in small_values:
            idx = val_to_idx[v]
            for k in range(v, threshold + 1, v):
                buckets[k].append(idx)

        uf = DSU(m)

        # For each bucket, union all indices inside it
        for lst in buckets:
            if not lst:
                continue
            base = lst[0]
            for idx in lst[1:]:
                uf.union(base, idx)

        # Count distinct roots among small indices
        roots = set(uf.find(i) for i in range(m))
                   )
        return len(roots) + large_count


if __name__ == "__main__":
    # You can test your solution here
    pass

