import itertools, math
def dp_update_var(dp, M):
    n=len(dp)-1  # dp[1..M]
    new=[0]*(n+1)
    suffix=[0]*(n+2)
    for v in range(n,0,-1):
        suffix[v]=suffix[v+1]+dp[v]
    for w in range(1,n+1):
        new[w]=suffix[w+1]+dp[w]*(M-w+1)
    return new

def dp_update_fix(dp, f, M):
    new=[0]*(M+1)
    suffix=[0]*(M+2)
    for v in range(M,0,-1):
        suffix[v]=suffix[v+1]+dp[v]
    # new[f] = suffix[f]  (sum_{v>=f})
    new[f]=suffix[f]
    for w in range(1,f):
        new[w]=dp[w]
    return new

