def check_cycle(S):
    N=len(S)//2
    whites=[i+1 for i,ch in enumerate(S) if ch=='W']
    blacks=[i+1 for i,ch in enumerate(S) if ch=='B']
    for perm in permutations(blacks):
        f=[0]*(2*N+1)
        for w,b in zip(whites,perm):
            f[w]=b
        for b in blacks:
            if b<2*N:
                f[b]=b+1
        visited=[False]*(2*N+1)
        cycle=0
        for i in range(1,2*N+1):
            if not visited[i]:
                cur=i
                while not visited[cur]:
                    visited[cur]=True
                    cur=f[cur]
                cycle+=1
        if cycle!=1:
