#!/usr/bin/env python3
import sys

def min_cost_for_k(a,p,b,q,k):
    best = 10**30
    # iterate x in 0..b-1
    for x in range(b):
        need = k - a*x
        if need <= 0:
            y = 0
        else:
            y = (need + b - 1)//b
        cost = p*x + q*y
        if cost < best:
            best = cost
    # iterate y
    for y in range(a):
        need = k - b*y
        if need <= 0:
            x = 0
        else:
            x = (need + a - 1)//a
        cost = p*x + q*y
        if cost < best:
            best = cost
    return best


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    X = int(next(it))
    processes = []
    for _ in range(n):
        a = int(next(it)); p=int(next(it)); b=int(next(it)); q=int(next(it))
        processes.append((a,p,b,q))
    # upper bound
    high=0
    for a,p,b,q in processes:
        min_cost = p if p<q else q
        max_prod = a if a>b else b
        high_i = (X // min_cost) * max_prod
        if high_i>high:
            high=high_i
    low=0
    while low<high:
        mid=(low+high+1)//2
        total=0
        feasible=True
        for a,p,b,q in processes:
            cost=min_cost_for_k(a,p,b,q,mid)
            total+=cost
            if total> X:
                feasible=False
                break
        if feasible:
            low=mid
        else:
            high=mid-1
    print(low)

if __name__=='__main__':
    solve()

