def solve(inp: str):
    it=iter(inp.strip().split())
    N=int(next(it))
    p=int(next(it))
    A=[[int(next(it)) for _ in range(N)] for _ in range(N)]
    K=sum(1 for i in range(N) for j in range(N) if A[i][j]==0)
    M=[[0]*N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if A[i][j]==0:
                if i==j:
                    M[i][j]=1%p
                else:
                    M[i][j]=0
            else:
                M[i][j]=A[i][j]%p
    # matrix multiplication
    def mat_mult(A,B):
        N=len(A)
        res=[[0]*N for _ in range(N)]
        for i in range(N):
            Ai=A[i]
            Ri=res[i]
            for k in range(N):
                aik=Ai[k]
                if aik==0: continue
                Bk=B[k]
                for j in range(N):
                    Ri[j]=(Ri[j]+aik*Bk[j])%p
        return res
    def mat_pow(M,exp):
        N=len(M)
        result=[[0]*N for _ in range(N)]
        for i in range(N): result[i][i]=1
        base=M
        e=exp
        while e>0:
            if e&1:
                result=mat_mult(result,base)
            base=mat_mult(base,base)
            e>>=1
        return result
    Mp=mat_pow(M,p)
    fact=pow(p-1,K,p)
    for i in range(N):
        for j in range(N):
            Mp[i][j]=Mp[i][j]*fact%p
    return '\n'.join(' '.join(str(x) for x in row) for row in Mp)

