def feasible(H, U, D, X):
    N=len(U)
    low=max(0, H-D[0])
    high=min(U[0], H)
    if low>high:
        return False
    for i in range(1,N):
        new_low=max(L:=max(0, H-D[i]), low - X)
        new_high=min(R:=min(U[i], H), high + X)
        if new_low>new_high:
