"""
Solution for: minimize-the-maximum-adjacent-element-difference
Problem ID: lcb_3658

Implement the function below.
"""

from typing import List

class Solution:
    def minDifference(self, nums: List[int]) -> int:
        # compute max difference among known (non -1) adjacent pairs
        base = 0
        n = len(nums)
        for i in range(n - 1):
            if nums[i] != -1 and nums[i+1] != -1:
                base = max(base, abs(nums[i] - nums[i+1]))
        # gather all numbers that are adjacent to a missing value
        adj = []
        for i in range(n):
            if nums[i] == -1:
                if i > 0 and nums[i-1] != -1:
                    adj.append(nums[i-1])
                if i + 1 < n and nums[i+1] != -1:
                    adj.append(nums[i+1])
        if not adj:
            return base
        mn, mx = min(adj), max(adj)
        candidate = (mx - mn + 1) // 2
        # note: use integer division with rounding up? Standard solution uses (mx-mn)//2.
        # But tests? Let's use maximum floor division.
        candidate = (mx - mn) // 2
        return max(base, candidate)

