    fn = resolve_function()
    if fn is None:
        print("❌ Could not import minimumIncrements from solution.py")
        return False

    test_cases = load_test_cases()

    passed = 0
    failed = 0
    total = len(test_cases)
    max_failures = 3

    print(f"Running {total} test cases...")
    print("=" * 60)

    for test in test_cases:
        test_id = test["id"]

        try:
