"""
Solution for: minimum-increments-for-target-multiples-in-an-array
Problem ID: lcb_3697

Implement the function below.
"""

from typing import List

class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        # target length <=4
        tlen = len(target)
        # precompute lcm for every non-empty subset
        from math import gcd
        def lcm(a,b):
            return a//gcd(a,b)*b
        # mapping subset mask -> lcm
        subset_lcm = {}
        for mask in range(1, 1<<tlen):
            l = 1
            for i in range(tlen):
                if mask>>i & 1:
                    l = lcm(l, target[i])
            subset_lcm[mask] = l
        # compute minimal increments for each subset
        INF = 10**18
        cost = {mask: INF for mask in range(1, 1<<tlen)}
        for mask in range(1, 1<<tlen):
            l = subset_lcm[mask]
            best = INF
            for val in nums:
                r = val % l
                inc = 0 if r == 0 else l - r
                if inc < best:
                    best = inc
            cost[mask] = best
        # DP over masks to cover all targets
        dp = [INF] * (1<<tlen)
        dp[0] = 0
        for mask in range(1, 1<<tlen):
            sub = mask
            while sub:
                # use sub as one element covering sub
                if cost[sub] < INF:
                    dp[mask] = min(dp[mask], dp[mask^sub] + cost[sub])
                sub = (sub-1) & mask
        return dp[(1<<tlen)-1]

