def exists_cycle_B(B):
    N=B
    limit=4
    cells=[(r,c) for r in range(limit) for c in range(limit)]
    for perm in itertools.permutations(cells, N):
        ok=True
        for i in range(N):
            r1,c1=perm[i]
            r2,c2=perm[(i+1)%N]
            dr=abs(r1-r2); dc=abs(c1-c2)
            if not (dr==1 and dc==1):
