class Solution:
    def maxCollectedFruits(self, fruits: List[List[int]]) -> int:
        n = len(fruits)
        if n == 0:
            return 0

        # Define moves for each child
        moves1 = [(1, 0), (0, 1), (1, 1)]          # (0,0) start
        moves2 = [(1, 0), (1, 1), (1, -1)]         # (0,n-1) start
        moves3 = [(-1, 0), (0, 1), (1, 1)]          # (n-1,0) start

        def get_path(start: Tuple[int, int], moves: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
            # DP arrays: current and previous step
            dp_prev: Dict[Tuple[int, int], int] = {start: fruits[start[0]][start[1]]}
            prev: List[Dict[Tuple[int, int], Tuple[int, int]]] = [{}]  # predecessor mapping per step

            for step in range(1, n):
                dp_curr: Dict[Tuple[int, int], int] = {}
                prev_map: Dict[Tuple[int, int], Tuple[int, int]] = {}
                for (i, j), val in dp_prev.items():
                    for di, dj in moves:
                        ni, nj = i + di, j + dj
                        if 0 <= ni < n and 0 <= nj < n:
                            nv = val + fruits[ni][nj]
                            if nv > dp_curr.get((ni, nj), -1):
                                dp_curr[(ni, nj)] = nv
                                prev_map[(ni, nj)] = (i, j)
                if not dp_curr:
                    # No reachable positions (should not happen)
                    return []
                dp_prev = dp_curr
                prev.append(prev_map)

            target = (n - 1, n - 1)
