def count_compatible(d):
    import random
    # generate a random state of length d with no equal adjacent
    state=[0]
    for i in range(1,d):
        state.append(random.choice([c for c in [0,1,2] if c!=state[-1]])
    # count compatible states
    count=0
    for t0 in range(3):
        if t0==state[0]: continue
        stack=[(1,t0,[t0])]
        while stack:
            i,prev,arr=stack.pop()
            if i==d:
                count+=1
            else:
                for c in range(3):
                    if c==state[i] or c==prev: continue
                    stack.append((i+1,c,arr+[c]))
    return count

