MOD=998244353

def precompute(maxA):
    # compute phi
    phi=list(range(maxA+1))
    for i in range(2, maxA+1):
        if phi[i]==i:
            for j in range(i, maxA+1, i):
                phi[j]-=phi[j]//i
    # compute divisors list
    divisors=[[] for _ in range(maxA+1)]
    for d in range(1, maxA+1):
        for mult in range(d, maxA+1, d):
