import sys

class BIT:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)
    def add(self, i, v):
        while i <= self.n:
            self.bit[i] += v
            i += i & -i
    def find_kth(self, k):
        idx = 0
        mask = 1
        while mask << 1 <= self.n:
            mask <<= 1
        while mask:
            t = idx + mask
            if t <= self.n and self.bit[t] < k:
                k -= self.bit[t]
                idx = t
            mask >>= 1
        return idx + 1

def solve():
    data = list(map(int, sys.stdin.read().split()))
    n = data[0]
    P = data[1:]
    bit = BIT(n)
    for i in range(1, n + 1):
        bit.add(i, 1)
    res = [0] * n
    for i in range(n, 0, -1):
        pos = bit.find_kth(P[i - 1])
        res[pos - 1] = i
        bit.add(pos, -1)
    print(' '.join(map(str, res)))

if __name__ == "__main__":
    solve()

