import itertools, math
def count_paths(W,H,L,R,D,U):
    allowed=set()
    for x in range(W+1):
        for y in range(H+1):
            if not (L<=x<=R and D<=y<=U):
                allowed.add((x,y))
    # DP: number of paths starting at each node
    dp={}
    # iterate from top-right downwards
    for y in range(H,-1,-1):
        for x in range(W,-1,-1):
            if (x,y) not in allowed: continue
