import random, heapq

def solve_sim(H,W,X,P,Q,grid):
    visited=[[False]*W for _ in range(H)]
    S=grid[P-1][Q-1]
    visited[P-1][Q-1]=True
    heap=[]
    dirs=[(1,0),(-1,0),(0,1),(0,-1)]
    def add_neighbors(i,j):
        for di,dj in dirs:
            ni,nj=i+di,j+dj
            if 0<=ni<H and 0<=nj<W and not visited[ni][nj]:
                heapq.heappush(heap,(grid[ni][nj],ni,nj))
    add_neighbors(P-1,Q-1)
    while heap:
        s,i,j=heap[0]
        if s*X < S:
            heapq.heappop(heap)
            if visited[i][j]:
                continue
            visited[i][j]=True
            S+=s
            add_neighbors(i,j)
        else:
            break
    return S

