    sum_d2=sum(N-abs(k-(N+1)) for k in D2)
    sum1=sum_rows+sum_cols+sum_d1+sum_d2
    row_col=a*b
    def inter_row_d1():
        cnt=0
        for i in R:
            for d in D1:
                j=i-d
                if 1<=j<=N:
                    cnt+=1
        return cnt
    row_d1=inter_row_d1()
    def inter_row_d2():
        cnt=0
        for i in R:
            for d in D2:
                j=d-i
                if 1<=j<=N:
                    cnt+=1
        return cnt
    row_d2=inter_row_d2()
    def inter_col_d1():
        cnt=0
        for j in C:
            for d in D1:
                i=j+d
                if 1<=i<=N:
                    cnt+=1
        return cnt
    col_d1=inter_col_d1()
    def inter_col_d2():
        cnt=0
        for j in C:
            for d in D2:
                i=d-j
                if 1<=i<=N:
                    cnt+=1
        return cnt
    col_d2=inter_col_d2()
    def inter_d1d2():
        cnt=0
        for d1 in D1:
            for d2 in D2:
                if (d1+d2)%2==0:
                    i=(d1+d2)//2; j=(d2-d1)//2
                    if 1<=i<=N and 1<=j<=N:
                        cnt+=1
        return cnt
    d1_d2=inter_d1d2()
    sum2=row_col+row_d1+row_d2+col_d1+col_d2+d1_d2
    def sum_3_rc_d1():
        cnt=0
        for i in R:
            for j in C:
                if (i-j) in D1:
                    cnt+=1
        return cnt
    def sum_3_rc_d2():
        cnt=0
        for i in R:
            for j in C:
                if (i+j) in D2:
                    cnt+=1
        return cnt
    def sum_3_rd1d2():
        cnt=0
        for d1 in D1:
            for d2 in D2:
                if (d1+d2)%2==0:
                    i=(d1+d2)//2; j=(d2-d1)//2
                    if 1<=i<=N and 1<=j<=N and i in R:
                        cnt+=1
        return cnt
    def sum_3_cd1d2():
        cnt=0
        for d1 in D1:
            for d2 in D2:
                if (d1+d2)%2==0:
                    i=(d1+d2)//2; j=(d2-d1)//2
                    if 1<=i<=N and 1<=j<=N and j in C:
                        cnt+=1
        return cnt
    sum3=sum_3_rc_d1()+sum_3_rc_d2()+sum_3_rd1d2()+sum_3_cd1d2()
    quad=0
    for i in R:
        for j in C:
            if (i-j) in D1 and (i+j) in D2:
                quad+=1
    U=sum1-sum2+sum3-quad
    return total-U


def main():
