import math


def solve():
    input = sys.stdin.readline
    N, M, Q = map(int, input().split())
    edges = [None]  # 1-indexed
    for i in range(1, M+1):
        a,b,c = map(int, input().split())
        edges.append((a,b,c))
    queries = []
    for _ in range(Q):
        parts = input().split()
        if parts[0] == '1':
            queries.append((1, int(parts[1])))
        else:
            queries.append((2, int(parts[1]), int(parts[2])))

    INF = 10**18
    # compute initial all-pairs
    dist = [[INF]*(N+1) for _ in range(N+1)]
    for i in range(1,N+1):
        dist[i][i]=0
    for idx in range(1, M+1):
        a,b,c = edges[idx]
        if c<dist[a][b]:
            dist[a][b]=c
            dist[b][a]=c
    # Floyd
    for k in range(1,N+1):
        for i in range(1,N+1):
            if dist[i][k]==INF: continue
            for j in range(1,N+1):
                if dist[k][j]==INF: continue
                v = dist[i][k]+dist[k][j]
                if v<dist[i][j]:
                    dist[i][j]=v
    closed = set()
    out_lines=[]
    for q in queries:
        if q[0]==1:
            idx = q[1]
            closed.add(idx)
            # recompute dist from scratch excluding closed edges
            dist = [[INF]*(N+1) for _ in range(N+1)]
            for i in range(1,N+1):
                dist[i][i]=0
            for iedge in range(1, M+1):
                if iedge in closed: continue
                a,b,c = edges[iedge]
                if c<dist[a][b]:
                    dist[a][b]=c
                    dist[b][a]=c
            # Floyd again
            for k in range(1,N+1):
                for i in range(1,N+1):
                    if dist[i][k]==INF: continue
                    for j in range(1,N+1):
                        if dist[k][j]==INF: continue
                        v = dist[i][k]+dist[k][j]
                        if v<dist[i][j]:
                            dist[i][j]=v
        else:
            x,y = q[1], q[2]
            ans = dist[x][y]
            out_lines.append(str(ans if ans!=INF else -1))
    print("\n".join(out_lines))

if __name__=="__main__":
    solve()

