import sys

def fwht(a, inverse):
    n = len(a)
    step = 1
    while step < n:
        for i in range(0, n, step * 2):
            for j in range(step):
                u = a[i + j]
                v = a[i + j + step]
                a[i + j] = u + v
                a[i + j + step] = u - v
        step <<= 1
    if inverse:
        # divide by n (which is power of two, integer division works)
        for i in range(n):
            a[i] //= n


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    H = int(next(it))
    W = int(next(it))
    rows = []
    for _ in range(H):
        s = next(it)
        mask = 0
        for i, ch in enumerate(s):
            if ch == '1':
                mask |= 1 << i
        rows.append(mask)

    N = 1 << W
    f = [0] * N
    for r in rows:
        f[r] += 1

    # weight for each xor result: minimal flips needed to zero the row
    w = [0] * N
    for t in range(N):
        cnt = bin(t).count('1')
        w[t] = min(cnt, W - cnt)

    fwht(f, False)
    fwht(w, False)
    for i in range(N):
        f[i] *= w[i]
    fwht(f, True)

    ans = min(f)
    print(ans)


if __name__ == "__main__":
    solve()

