import sys

def solve():
    data=sys.stdin.read().strip().split()
    if not data:
        return
    it=iter(data)
    N=int(next(it))
    A=[int(next(it)) for _ in range(N)]
    B=[int(next(it)) for _ in range(N)]
    C=[int(next(it)) for _ in range(N)]
    S0=0
    for a,c in zip(A,C):
        S0+=a*c
    dec=[]
    inc=[]
    for a,b,c in zip(A,B,C):
        if a!=b:
            if a==1:
                dec.append(c)
            else:
                inc.append(c)
    dec.sort(reverse=True)
    inc.sort()
    total=0
    S=S0
    for c in dec:
        S-=c
        total+=S
    for c in inc:
        S+=c
        total+=S
    print(total)

if __name__=='__main__':
    solve()

