import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    s = data[1].strip()
    t = data[2].strip()
    mapping = {}
    for i in range(n):
        a = s[i]
        b = t[i]
        if a == b:
            continue
        if a in mapping:
            if mapping[a] != b:
                print(-1)
                return
        else:
            mapping[a] = b
    # Build graph
    out = {c: mapping[c] for c in mapping}
    edges = len(out)
    # Detect cycles
    cycle_count = 0
    visited = {}  # 0 unvisited,1 visiting,2 visited
    for c in out:
        if c in visited:
            continue
        stack = []
        cur = c
        while True:
            if cur not in out:
                # reached node with no outgoing edge
                for node in stack:
                    visited[node] = 2
                break
            if cur in visited:
                if visited[cur] == 1:
                    # found cycle, count all nodes in cycle part
                    # iterate from cur to end of stack
                    cycle_found = False
                    for node in stack:
                        if node == cur:
                            cycle_found = True
                        if cycle_found:
                            visited[node] = 2
                    cycle_count += 1
                else:
                    # visited and finished
                    for node in stack:
                        visited[node] = 2
                break
            # mark visiting
            visited[cur] = 1
            stack.append(cur)
            cur = out[cur]
    ans = edges + cycle_count
    print(ans)

if __name__ == "__main__":
    solve()

