import random

def brute(A):
    N=len(A)
    best=0
    for l in range(N+1):
        for r in range(l+1,N+1):
            sub=A[l:r]
            if len(sub)%2!=0: continue
            ok=True
            counts={}
            for i in range(0,len(sub),2):
                if sub[i]!=sub[i+1]: ok=False;break
                val=sub[i]
                if val in counts: ok=False;break
                counts[val]=1
            if ok:
                best=max(best,len(sub))
    return best

def solve(A):
    N=len(A)
    pairs=[i for i in range(N-1) if A[i]==A[i+1]]
    freq={}
    l=0
    ans=0
    for r in range(len(pairs)):
        if r>l and pairs[r]!=pairs[r-1]+2:
            l=r
            freq={}
        val=A[pairs[r]]
        while val in freq:
            freq.pop(A[pairs[l]], None)
            l+=1
        freq[val]=1
        ans=max(ans, 2*(r-l+1))
    return ans

for N in range(1,11):
    for _ in range(2000):
        A=[random.randint(1,3) for _ in range(N)]
        b=brute(A)
        s=solve(A)
        if b!=s:
            print('Mismatch',A,b,s)
            raise SystemExit
print('all ok')

