import math, random

def dist(a,b,N):
    return min((b-a+N)%N, (a-b+N)%N)

def dp_transform(arr,N):
    # arr length N
    # compute g[x] = min_y arr[y] + dist(y,x)
    # use 2N extension
    A = arr + arr  # length 2N
    # forward pass
    best = 10**9
    for i in range(2*N):
        best = min(best+1, A[i])
        A[i] = best
    # backward pass
    best = 10**9
    for i in range(2*N-1,-1,-1):
        best = min(best+1, A[i])
        A[i] = best
    g = [min(A[i], A[i+N]) for i in range(N)]
    return g

# test random
def brute(arr,N):
    g=[10**9]*N
    for x in range(N):
        g[x]=min(arr[y]+dist(y,x,N) for y in range(N))
    return g

for N in [5,6,7]:
    for _ in range(100):
        arr=[random.randint(0,20) for _ in range(N)]
        if dp_transform(arr,N)!=brute(arr,N):
            print("Mismatch",N)
            break
print("done")

