import heapq

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(map(int, data))
    t = next(it)
    out_lines = []
    for _ in range(t):
        n = next(it)
        k = next(it)
        a = [next(it) for _ in range(n)]
        b = [next(it) for _ in range(n)]
        # sort indices by a ascending
        idx_sorted = sorted(range(n), key=lambda i: a[i])
        heap = []  # max-heap via negatives
        sum_heap = 0
        need = k - 1
        ans = None
        for idx in idx_sorted:
            if need == 0:
                candidate = a[idx] * b[idx]
                if ans is None or candidate < ans:
                    ans = candidate
            else:
                if len(heap) == need:
                    candidate = a[idx] * (b[idx] + sum_heap)
                    if ans is None or candidate < ans:
                        ans = candidate
                # update heap for future candidates
                if len(heap) < need:
                    heapq.heappush(heap, -b[idx])
