MOD = 998244353

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    K = int(next(it))
    A = [int(next(it)) % MOD for _ in range(N)]

    # prefix sums P[0]..P[N]
    P = [0]*(N+1)
    for i in range(1, N+1):
        P[i] = (P[i-1] + A[i-1]) % MOD

    # precompute powers of prefix sums
    # powP[p][i] = P[i]^p
    powP = [[0]*(N+1) for _ in range(K+1)]
    for p in range(K+1):
        for i in range(N+1):
            if p == 0:
                powP[p][i] = 1  # x^0 = 1, including 0^0
            else:
                powP[p][i] = pow(P[i], p, MOD)

