from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        # Directions in order of clockwise rotation
        dirs = [(1,1), (1,-1), (-1,-1), (-1,1)]
        # Pre-compute dp arrays for each direction
        # We'll keep for each direction two arrays: len0 and len2
        len0 = [[[0]*m for _ in range(n)] for _ in range(4)]
        len2 = [[[0]*m for _ in range(n)] for _ in range(4)]
        for d_idx,(dr,dc) in enumerate(dirs):
            # Determine iteration order based on direction
            if dr>=0:
                i_range = range(n-1,-1,-1)
            else:
                i_range = range(n)
            if dc>=0:
                j_range = range(m-1,-1,-1)
            else:
                j_range = range(m)
            for i in i_range:
                for j in j_range:
                    ni = i+dr
                    nj = j+dc
                    if 0<=ni<n and 0<=nj<m:
                        # next cell exists
                        if grid[i][j]==2:
                            len2[d_idx][i][j] = 1 + len0[d_idx][ni][nj]
                        else:
                            len2[d_idx][i][j] = 0
                        if grid[i][j]==0:
                            len0[d_idx][i][j] = 1 + len2[d_idx][ni][nj]
                        else:
                            len0[d_idx][i][j] = 0
                    else:
                        len2[d_idx][i][j] = 1 if grid[i][j]==2 else 0
                        len0[d_idx][i][j] = 1 if grid[i][j]==0 else 0
        # Helper to get remaining straight length from a cell in dir_idx with expected value
        def rem_length(dir_idx, i, j, expect):
            if not (0<=i<n and 0<=j<m):
                return 0
            if expect==0:
                return len0[dir_idx][i][j]
            else: # expect==2
                return len2[dir_idx][i][j]
        best = 0
        for si in range(n):
            for sj in range(m):
                if grid[si][sj]!=1:
                    continue
                # Simulate straight segments from this start in each dir
                for d_idx,(dr,dc) in enumerate(dirs):
                    i, j = si, sj
                    step = 0
                    # We will store path coordinates for turning evaluation
                    path = []
                    while 0<=i<n and 0<=j<m:
                        path.append((i,j,step))
                        step +=1
                        i+=dr
                        j+=dc
                    # For each point along path evaluate turning to the next direction
                    for turn_step, (ti,tj,tindex) in enumerate(path):
                        # count length so far up to this cell (including it)
                        len_until = tindex+1
                        # Next direction is clockwise: next_dir index = (d_idx+1)%4
                        nd = (d_idx+1)%4
                        ndir = dirs[nd]
                        nx = ti+ndir[0]
                        ny = tj+ndir[1]
                        # Expected value after current cell: if (tindex+1)%2==1 -> 2 else 0
                        next_expect = 2 if ((tindex+1)&1)==1 else 0
                        remaining = rem_length(nd, nx, ny, next_expect)
                        total = len_until + remaining
                        if total>best:
                            best=total
        return best

if __name__ == "__main__":
    # You can test your solution here
    pass

