#!/usr/bin/env python3
import sys

MOD = 10 ** 9 + 7

# Mapping of characters to index
char_to_int = {"F": 0, "W": 1, "E": 2}

# Outcome table: outcome[Bob][Alice] -> Bob's points from that round
# +1 if Bob beats Alice, -1 if Alice beats Bob, 0 if tie
outcome = [[0] * 3 for _ in range(3)]
for i in range(3):
    for j in range(3):
        if i == j:
            outcome[i][j] = 0
        elif (i == 0 and j == 2) or (i == 1 and j == 0) or (i == 2 and j == 1):
            outcome[i][j] = 1
        else:
            outcome[i][j] = -1

def count_beating_sequences(s: str) -> int:
    """Return number of distinct Bob sequences that beat Alice."""
    n = len(s)
    a = [char_to_int[ch] for ch in s]
    offset = n
    # dp[last][diff_offset] = number ways for processed prefix and Bob's score relative to Alice = diff
    dp_prev = [[0] * (2 * n + 1) for _ in range(3)]
    # first round, no restriction on previous move
    for move in range(3):
        diff = outcome[move][a[0]]
        dp_prev[move][diff + offset] = (dp_prev[move][diff + offset] + 1) % MOD
    # iterate rounds 2..n
    for idx in range(1, n):
        dp_next = [[0] * (2 * n + 1) for _ in range(3)]
        for last in range(3):
            row = dp_prev[last]
            for d in range(-offset, offset + 1):
                cnt = row[d + offset]
                if cnt == 0:
                    continue
                for move in range(3):
                    if move == last:
                        continue
                    delta = outcome[move][a[idx]]
                    nd = d + delta
                    dp_next[move][nd + offset] = (dp_next[move][nd + offset] + cnt) % MOD
        dp_prev = dp_next
    # sum over all states with diff > 0
    ans = 0
    for last in range(3):
        for d in range(1, offset + 1):
            ans = (ans + dp_prev[last][d + offset]) % MOD
    return ans

if __name__ == "__main__":
    s = sys.stdin.readline().strip()
    print(count_beating_sequences(s))

