"""
Solution for: count-k-reducible-numbers-less-than-n
Problem ID: lcb_3631

Implement the function below.
"""

MOD = 10**9 + 7

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = len(s)
        # precompute combinatorics up to n
        comb = [[0]*(n+1) for _ in range(n+1)]
        for i in range(n+1):
            comb[i][0] = 1
            for j in range(1, i+1):
                comb[i][j] = (comb[i-1][j-1] + comb[i-1][j]) % MOD
        # function to count numbers < int(s) with exactly v ones
        def count_with_popcount(v: int) -> int:
            res = 0
            ones_needed = v
            for i, ch in enumerate(s):
                if ch == '1':
                    bits_remaining = n - i - 1
                    if ones_needed <= bits_remaining:
                        res = (res + comb[bits_remaining][ones_needed]) % MOD
                    if ones_needed == 0:
                        return res
                    ones_needed -= 1
            # if we finish loop and ones_needed==0, we have counted all < n (n itself not counted)
            return res

        # precompute goodness for values up to n (max popcount)
        max_val = n  # maximum possible popcount
        # good[t][v] is whether integer v is reducible in <= t operations
        good = [[False]*(max_val+1) for _ in range(k+1)]
        # base: 0 ops, only 1 is reducible
        good[0][1] = True
        for t in range(1, k+1):
            for v in range(1, max_val+1):
                if v == 1:
                    good[t][v] = True
                else:
                    pc = bin(v).count('1')
                    good[t][v] = good[t-1][pc]
        # We need popcounts that are reducible in <= k-1 ops
        allowed = set()
        for v in range(1, max_val+1):
            if good[k-1][v]:
                allowed.add(v)
        ans = 0
        for v in allowed:
            ans = (ans + count_with_popcount(v)) % MOD
        return ans

